using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using System.IO;using System.Linq;
public static class CoastTreeReview{public static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);var sun=new GameObject().AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(40,-30,0);RenderSettings.ambientLight=Color.gray;for(int i=0;i<5;i++){string name="CommonTree_"+(i+1)+".fbx";var path=AssetDatabase.FindAssets(Path.GetFileNameWithoutExtension(name)+" t:Model").Select(AssetDatabase.GUIDToAssetPath).First(p=>Path.GetFileName(p)==name);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.localScale*=5/b.size.y;g.transform.position=new Vector3(i*5,0,0);}
var c=new GameObject().AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.65f,.8f,.9f);c.transform.position=new Vector3(10,4,-22);c.transform.LookAt(new Vector3(10,2,0));c.orthographic=true;c.orthographicSize=4.4f;var rt=new RenderTexture(1800,600,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1800,600,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1800,600),0,0);t.Apply();File.WriteAllBytes("ArtSource/Lighthouse_Authored/TreeReview.png",t.EncodeToPNG());}}
